<script setup lang="ts">
    // types
    type Props = {
        iconName?:
            | 'record-list'
            | 'up'
            | 'down'
            | 'record-repeat'
            | 'track-repeat'
            | 'section-repeat'
            | 'bar-repeat'
            | 'no-repeat'
        height?: string
        width?: string
        fill?: 0 | 1
    }

    // props
    const {
        iconName = 'record-list',
        height = 'fit-content',
        width = 'fit-content',
        fill = 0,
    } = defineProps<Props>()

    const appConfig = useAppConfig()
    const { isDarkMode } = useDarkMode()

    const fillColor = computed(() => {
        if (fill === 1) {
            return 'currentColor'
        } else {
            return isDarkMode.value
                ? appConfig.dark.background
                : appConfig.color.background
        }
    })
</script>

<style scoped>
    .app-icon {
        line-height: 0;
        width: v-bind(width);
        height: v-bind(height);
    }
    svg {
        width: 100%;
        height: 100%;
    }
    .record-list-icon,
    .record-repeat-icon,
    .track-repeat-icon,
    .section-repeat-icon,
    .bar-repeat-icon,
    .no-repeat-icon {
        fill: currentColor;
    }
    .up-icon,
    .down-icon {
        stroke-width: 3px;
        stroke: currentColor;
        fill: v-bind(fillColor);
    }
</style>
